{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE vahdam_db.maplemonk.vahdam_us_d2c_pnl_line_level AS WITH mapping AS ( SELECT TRIM(\"D2C US\") AS d2c_us_sku, ANY_VALUE(TRIM(\"Common SKU ID\")) AS common_sku_id, ANY_VALUE(TRIM(\"Common SKU Description\")) AS common_sku_description, ANY_VALUE(BRAND) AS brand, ANY_VALUE(CATEGORY) AS category, ANY_VALUE(\"Sub-category\") AS sub_category FROM vahdam_db.maplemonk.vahdam_fy27_inputs_product_mapping WHERE \"D2C US\" IS NOT NULL AND TRIM(\"D2C US\") != \'\' GROUP BY TRIM(\"D2C US\") ), cost_sheet AS ( SELECT TRIM(SKU) AS sku, NULLIF(TRY_TO_DECIMAL(REPLACE(\"COGS (INR)\",\',\',\'\'),30,5), 0) AS cogs_inr, NULLIF(TRY_TO_DECIMAL(REPLACE(\"Duty (USD)\",\',\',\'\'),30,5), 0) AS duty_usd, NULLIF(TRY_TO_DECIMAL(REPLACE(\"Outbound(USD)\",\',\',\'\'),30,5), 0) AS outbound_usd, NULLIF(TRY_TO_DECIMAL(REPLACE(\"Last Mile / mcf (USD)\",\',\',\'\'),30,5), 0) AS lastmile_per_unit_usd FROM vahdam_db.maplemonk.fy27_inputs_d2c_usa_sc_costs WHERE TRIM(SKU) IS NOT NULL AND TRIM(SKU) != \'\' ), cost_via_common_ranked AS ( SELECT c.sku AS cost_sku, m.common_sku_id, c.cogs_inr, c.duty_usd, c.outbound_usd, c.lastmile_per_unit_usd, ROW_NUMBER() OVER ( PARTITION BY m.common_sku_id ORDER BY CASE WHEN LOWER(c.sku) LIKE \'%frother%\' THEN 1 ELSE 0 END + CASE WHEN LOWER(c.sku) LIKE \'%gift%\' THEN 1 ELSE 0 END + CASE WHEN LOWER(c.sku) LIKE \'%bundle%\' THEN 1 ELSE 0 END + CASE WHEN LOWER(c.sku) LIKE \'%kit%\' THEN 1 ELSE 0 END + CASE WHEN LOWER(c.sku) LIKE \'%pack of%\' THEN 1 ELSE 0 END, LENGTH(c.sku) ) AS rn FROM cost_sheet c JOIN mapping m ON m.d2c_us_sku = c.sku WHERE c.cogs_inr IS NOT NULL ), cost_via_common AS ( SELECT cost_sku, common_sku_id, cogs_inr, duty_usd, outbound_usd, lastmile_per_unit_usd FROM cost_via_common_ranked WHERE rn = 1 ), fx_monthly AS ( SELECT TRY_TO_DATE(\"MONTH\", \'DD-Mon-YY\') AS month_start, MAX(TRY_TO_DECIMAL(REPLACE(FX,\',\',\'\'),30,5)) AS fx_inr_per_usd FROM vahdam_db.maplemonk.vahdam_budget_amazon_3p___1p_budget WHERE UPPER(GEOGRAPHY) = \'USA\' AND FX IS NOT NULL AND TRY_TO_DATE(\"MONTH\", \'DD-Mon-YY\') IS NOT NULL GROUP BY TRY_TO_DATE(\"MONTH\", \'DD-Mon-YY\') ), fx_geo_avg AS ( SELECT AVG(fx_inr_per_usd) AS fx_geo_avg_us FROM fx_monthly ), pg_fees AS ( SELECT SOURCE_ORDER_ID AS ORDER_ID, SUM(FEE) AS pg_fee_usd_order FROM VAHDAM_DB.MAPLEMONK.SHOPIFYUS_BALANCE_TRANSACTIONS WHERE TYPE = \'charge\' GROUP BY SOURCE_ORDER_ID ), pm_daily_meta AS ( SELECT DATE_START AS day, SUM(SPEND) AS meta_spend_usd, CAMPAIGN_NAME FROM vahdam_db.maplemonk.meta_usa_customcampaigns_data WHERE CAMPAIGN_NAME NOT ILIKE \'%AWAR%\' GROUP BY DATE_START, CAMPAIGN_NAME ), pm_daily_google AS ( SELECT SEGMENTS_DATE::DATE AS day, CAMPAIGN_NAME AS campaign_name, SUM(SPEND) AS google_spend_usd FROM vahdam_db.maplemonk.us_google_ads_consolidated GROUP BY SEGMENTS_DATE::DATE, CAMPAIGN_NAME ), pm_with_category AS ( SELECT day, \'META\' AS source, campaign_name, meta_spend_usd AS spend_usd, CASE WHEN UPPER(campaign_name) LIKE \'%COFFEE%\' THEN \'Coffee\' WHEN UPPER(campaign_name) LIKE \'%SUPP%\' THEN \'Supplements\' ELSE \'Tea and Botanicals\' END AS mapped_category FROM pm_daily_meta UNION ALL SELECT day, \'GOOGLE\' AS source, campaign_name, google_spend_usd AS spend_usd, CASE WHEN UPPER(campaign_name) LIKE \'%COFFEE%\' THEN \'Coffee\' WHEN UPPER(campaign_name) LIKE \'%SUPP%\' THEN \'Supplements\' ELSE \'Tea and Botanicals\' END AS mapped_category FROM pm_daily_google ), pm_day_source_cat AS ( SELECT day, source, mapped_category, SUM(spend_usd) AS spend_usd FROM pm_with_category GROUP BY day, source, mapped_category ), line_base AS ( SELECT DATE(o.ORDER_TIMESTAMP) AS day, o.ORDER_TIMESTAMP, o.ORDER_ID, o.ORDER_NAME, o.LINE_ITEM_ID, LOWER(TRIM(o.EMAIL)) AS customer_email, o.CUSTOMER AS customer_id, TRIM(o.SKU) AS line_item_sku, o.PRODUCT_NAME, o.VARIANT_NAME, o.QUANTITY AS qty, o.GROSS_SALES_BEFORE_TAX AS gross_sales_local, o.DISCOUNT_BEFORE_TAX AS discount_local, o.NET_SALES_BEFORE_TAX AS net_sales_local_raw, (COALESCE(o.GROSS_SALES_BEFORE_TAX,0) - COALESCE(o.DISCOUNT_BEFORE_TAX,0)) AS product_revenue_local, o.IS_REFUND, COALESCE(o.REFUND_VALUE, 0) AS refund_value_local, COALESCE(o.REFUND_QUANTITY, 0) AS refund_qty, o.SHIPPING_PRICE AS shipping_price_order_local, o.DISCOUNT AS discount_order_local, o.TOTAL_SALES AS total_sales_order_local, o.TAGS, o.SOURCE AS shopify_source, o.SHOPIFYQL_MAPPED_CHANNEL, o.SHOPIFYQL_MAPPED_SOURCE, o.FINAL_UTM_SOURCE, o.FINAL_UTM_CHANNEL, o.FINAL_UTM_CAMPAIGN, o.GATEWAY, o.PINCODE FROM vahdam_db.maplemonk.shopifyusa_all_orders_items o WHERE o.ORDER_STATUS != \'CANCELLED\' AND o.SKU IS NOT NULL AND TRIM(o.SKU) != \'\' ), customer_history AS ( SELECT customer_email, ORDER_ID, ORDER_TIMESTAMP, DENSE_RANK() OVER ( PARTITION BY customer_email ORDER BY ORDER_TIMESTAMP, ORDER_ID ) AS order_number_for_customer, LAG(ORDER_TIMESTAMP) OVER ( PARTITION BY customer_email ORDER BY ORDER_TIMESTAMP ) AS prev_order_ts, MIN(ORDER_TIMESTAMP) OVER (PARTITION BY customer_email) AS customer_first_order_ts FROM ( SELECT DISTINCT customer_email, ORDER_ID, ORDER_TIMESTAMP FROM line_base WHERE customer_email IS NOT NULL AND customer_email != \'\' ) ), customer_cumulative AS ( SELECT customer_email, ORDER_ID, SUM(SUM(product_revenue_local)) OVER ( PARTITION BY customer_email ORDER BY ORDER_TIMESTAMP, ORDER_ID ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS customer_revenue_to_date, SUM(SUM(qty)) OVER ( PARTITION BY customer_email ORDER BY ORDER_TIMESTAMP, ORDER_ID ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS customer_units_to_date FROM line_base WHERE customer_email IS NOT NULL AND customer_email != \'\' GROUP BY customer_email, ORDER_ID, ORDER_TIMESTAMP ), customer_acquisition AS ( SELECT customer_email, FINAL_UTM_SOURCE AS acquisition_utm_source, FINAL_UTM_CHANNEL AS acquisition_utm_channel, FINAL_UTM_CAMPAIGN AS acquisition_utm_campaign, SHOPIFYQL_MAPPED_CHANNEL AS acquisition_mapped_channel, SHOPIFYQL_MAPPED_SOURCE AS acquisition_mapped_source FROM ( SELECT customer_email, FINAL_UTM_SOURCE, FINAL_UTM_CHANNEL, FINAL_UTM_CAMPAIGN, SHOPIFYQL_MAPPED_CHANNEL, SHOPIFYQL_MAPPED_SOURCE, ROW_NUMBER() OVER ( PARTITION BY customer_email ORDER BY ORDER_TIMESTAMP, ORDER_ID ) AS rn FROM line_base WHERE customer_email IS NOT NULL AND customer_email != \'\' ) WHERE rn = 1 ), order_totals AS ( SELECT ORDER_ID, SUM(qty) AS order_total_qty, SUM(product_revenue_local) AS order_total_product_revenue, SUM(net_sales_local_raw) AS order_total_net_raw, ANY_VALUE(day) AS order_day FROM line_base GROUP BY ORDER_ID ), day_category_revenue AS ( SELECT l.day, COALESCE(m.category, \'Tea and Botanicals\') AS category, SUM(l.product_revenue_local) AS cat_product_revenue FROM line_base l LEFT JOIN mapping m ON m.d2c_us_sku = l.line_item_sku GROUP BY l.day, COALESCE(m.category, \'Tea and Botanicals\') ), enriched AS ( SELECT l.day, l.ORDER_TIMESTAMP, l.ORDER_ID, l.ORDER_NAME, l.LINE_ITEM_ID, l.line_item_sku, l.PRODUCT_NAME, l.VARIANT_NAME, m.common_sku_id, m.common_sku_description, m.brand, COALESCE(m.category, \'Tea and Botanicals\') AS category, m.sub_category, l.qty, l.gross_sales_local, l.discount_local, l.net_sales_local_raw, l.product_revenue_local, ROUND( CASE WHEN l.IS_REFUND = 0 OR l.IS_REFUND IS NULL THEN COALESCE(l.net_sales_local_raw,0) ELSE 0 END - COALESCE(l.refund_value_local,0) , 4) AS net_revenue_local, ROUND( CASE WHEN l.IS_REFUND = 0 OR l.IS_REFUND IS NULL THEN COALESCE(l.product_revenue_local,0) ELSE 0 END - COALESCE(l.refund_value_local,0) , 4) AS product_revenue_net_local, l.refund_value_local, l.refund_qty, l.IS_REFUND, CAST(0 AS DECIMAL(5,2)) AS vat_rate, ROUND( CASE WHEN l.IS_REFUND = 0 OR l.IS_REFUND IS NULL THEN COALESCE(l.product_revenue_local,0) ELSE 0 END - COALESCE(l.refund_value_local,0) , 4) AS product_revenue_net_ex_vat_local, CASE WHEN l.product_revenue_local <= 0.01 AND l.qty > 0 THEN \'FREE_GIFT\' WHEN l.product_revenue_local > 0 THEN \'PAID\' ELSE \'OTHER\' END AS line_type, cs_direct.cogs_inr AS direct_cogs_inr, cs_direct.duty_usd AS direct_duty_usd, cs_direct.outbound_usd AS direct_outbound_usd, cs_direct.lastmile_per_unit_usd AS direct_lastmile_per_unit_usd, cs_bridge.cogs_inr AS bridge_cogs_inr, cs_bridge.duty_usd AS bridge_duty_usd, cs_bridge.outbound_usd AS bridge_outbound_usd, cs_bridge.lastmile_per_unit_usd AS bridge_lastmile_per_unit_usd, COALESCE(fxm.fx_inr_per_usd, fxg.fx_geo_avg_us) AS fx_inr_per_usd, l.shipping_price_order_local, l.discount_order_local, l.total_sales_order_local, l.GATEWAY, l.PINCODE, ot.order_total_qty, ot.order_total_product_revenue, ot.order_total_net_raw, CASE WHEN ot.order_total_product_revenue > 0 THEN l.product_revenue_local / ot.order_total_product_revenue ELSE 0 END AS line_share_of_order_revenue, pg.pg_fee_usd_order, l.TAGS, (l.TAGS ILIKE \'%Subscription%\' OR l.TAGS ILIKE \'%Billing cycle%\') AS is_subscription_order, (l.TAGS ILIKE \'%Subscription First Order%\') AS is_subscription_first_order, (l.TAGS ILIKE \'%Subscription Recurring Order%\') AS is_subscription_recurring_order, TRY_TO_NUMBER(REGEXP_SUBSTR(l.TAGS, \'Billing Cycle #([0-9]+)\', 1, 1, \'ie\', 1)) AS billing_cycle_num, TRY_TO_NUMBER(REGEXP_SUBSTR(l.TAGS, \'Pay every ([0-9]+)\', 1, 1, \'ie\', 1)) AS billing_interval_value, UPPER(REGEXP_SUBSTR(l.TAGS, \'Pay every [0-9]+ (DAY|MONTH|WEEK)\', 1, 1, \'ie\', 1)) AS billing_interval_unit, l.customer_email, l.customer_id, ch.order_number_for_customer, (ch.order_number_for_customer = 1) AS is_first_order, (ch.order_number_for_customer > 1) AS is_repeat_order, ch.customer_first_order_ts, DATEDIFF(\'day\', ch.customer_first_order_ts, l.ORDER_TIMESTAMP) AS days_since_first_order, DATEDIFF(\'day\', ch.prev_order_ts, l.ORDER_TIMESTAMP) AS days_since_prev_order, cc.customer_revenue_to_date, cc.customer_units_to_date, ca.acquisition_utm_source, ca.acquisition_utm_channel, ca.acquisition_utm_campaign, ca.acquisition_mapped_channel, ca.acquisition_mapped_source, l.FINAL_UTM_SOURCE AS order_utm_source, l.FINAL_UTM_CHANNEL AS order_utm_channel, l.FINAL_UTM_CAMPAIGN AS order_utm_campaign, l.SHOPIFYQL_MAPPED_CHANNEL AS order_mapped_channel, l.SHOPIFYQL_MAPPED_SOURCE AS order_mapped_source FROM line_base l LEFT JOIN mapping m ON m.d2c_us_sku = l.line_item_sku LEFT JOIN cost_sheet cs_direct ON cs_direct.sku = l.line_item_sku AND cs_direct.cogs_inr IS NOT NULL LEFT JOIN cost_via_common cs_bridge ON cs_bridge.common_sku_id = m.common_sku_id AND m.common_sku_id IS NOT NULL LEFT JOIN fx_monthly fxm ON fxm.month_start = DATE_TRUNC(\'MONTH\', l.day) CROSS JOIN fx_geo_avg fxg LEFT JOIN order_totals ot ON ot.ORDER_ID = l.ORDER_ID LEFT JOIN pg_fees pg ON pg.ORDER_ID = l.ORDER_ID LEFT JOIN customer_history ch ON ch.ORDER_ID = l.ORDER_ID AND ch.customer_email = l.customer_email LEFT JOIN customer_cumulative cc ON cc.ORDER_ID = l.ORDER_ID AND cc.customer_email = l.customer_email LEFT JOIN customer_acquisition ca ON ca.customer_email = l.customer_email ), category_cost_ratios AS ( SELECT category, CASE WHEN SUM(CASE WHEN COALESCE(direct_cogs_inr, bridge_cogs_inr) IS NOT NULL THEN product_revenue_local ELSE 0 END) > 0 THEN SUM(CASE WHEN COALESCE(direct_cogs_inr, bridge_cogs_inr) IS NOT NULL THEN qty * COALESCE(direct_cogs_inr, bridge_cogs_inr) / NULLIF(fx_inr_per_usd,0) END) / NULLIF(SUM(CASE WHEN COALESCE(direct_cogs_inr, bridge_cogs_inr) IS NOT NULL THEN product_revenue_local ELSE 0 END),0) END AS cogs_pct, CASE WHEN SUM(CASE WHEN COALESCE(direct_duty_usd, bridge_duty_usd) IS NOT NULL THEN product_revenue_local ELSE 0 END) > 0 THEN SUM(CASE WHEN COALESCE(direct_duty_usd, bridge_duty_usd) IS NOT NULL THEN qty * COALESCE(direct_duty_usd, bridge_duty_usd) END) / NULLIF(SUM(CASE WHEN COALESCE(direct_duty_usd, bridge_duty_usd) IS NOT NULL THEN product_revenue_local ELSE 0 END),0) END AS duty_pct, CASE WHEN SUM(CASE WHEN COALESCE(direct_outbound_usd, bridge_outbound_usd) IS NOT NULL THEN product_revenue_local ELSE 0 END) > 0 THEN SUM(CASE WHEN COALESCE(direct_outbound_usd, bridge_outbound_usd) IS NOT NULL THEN qty * COALESCE(direct_outbound_usd, bridge_outbound_usd) END) / NULLIF(SUM(CASE WHEN COALESCE(direct_outbound_usd, bridge_outbound_usd) IS NOT NULL THEN product_revenue_local ELSE 0 END),0) END AS outbound_pct, CASE WHEN SUM(CASE WHEN COALESCE(direct_lastmile_per_unit_usd, bridge_lastmile_per_unit_usd) IS NOT NULL THEN product_revenue_local ELSE 0 END) > 0 THEN SUM(CASE WHEN COALESCE(direct_lastmile_per_unit_usd, bridge_lastmile_per_unit_usd) IS NOT NULL THEN qty * COALESCE(direct_lastmile_per_unit_usd, bridge_lastmile_per_unit_usd) END) / NULLIF(SUM(CASE WHEN COALESCE(direct_lastmile_per_unit_usd, bridge_lastmile_per_unit_usd) IS NOT NULL THEN product_revenue_local ELSE 0 END),0) END AS lastmile_pct FROM enriched WHERE product_revenue_local > 0 GROUP BY category ), enriched_with_fallbacks AS ( SELECT e.*, ccr.cogs_pct AS cat_cogs_pct, ccr.duty_pct AS cat_duty_pct, ccr.outbound_pct AS cat_outbound_pct, ccr.lastmile_pct AS cat_lastmile_pct, CASE WHEN e.direct_cogs_inr IS NOT NULL THEN \'DIRECT\' WHEN e.bridge_cogs_inr IS NOT NULL THEN \'BRIDGE\' WHEN ccr.cogs_pct IS NOT NULL THEN \'CAT_REV_PCT\' ELSE \'NO_MATCH\' END AS cogs_match_type, COALESCE( e.qty * e.direct_cogs_inr / NULLIF(e.fx_inr_per_usd,0), e.qty * e.bridge_cogs_inr / NULLIF(e.fx_inr_per_usd,0), e.product_revenue_local * ccr.cogs_pct, 0 ) AS cogs_usd_final, CASE WHEN e.direct_duty_usd IS NOT NULL THEN \'DIRECT\' WHEN e.bridge_duty_usd IS NOT NULL THEN \'BRIDGE\' WHEN ccr.duty_pct IS NOT NULL THEN \'CAT_REV_PCT\' ELSE \'NO_MATCH\' END AS duty_match_type, COALESCE( e.qty * e.direct_duty_usd, e.qty * e.bridge_duty_usd, e.product_revenue_local * ccr.duty_pct, 0 ) AS duty_usd_final, CASE WHEN e.direct_outbound_usd IS NOT NULL THEN \'DIRECT\' WHEN e.bridge_outbound_usd IS NOT NULL THEN \'BRIDGE\' WHEN ccr.outbound_pct IS NOT NULL THEN \'CAT_REV_PCT\' ELSE \'NO_MATCH\' END AS outbound_match_type, COALESCE( e.qty * e.direct_outbound_usd, e.qty * e.bridge_outbound_usd, e.product_revenue_local * ccr.outbound_pct, 0 ) AS outbound_usd_final, CASE WHEN e.direct_lastmile_per_unit_usd IS NOT NULL THEN \'DIRECT\' WHEN e.bridge_lastmile_per_unit_usd IS NOT NULL THEN \'BRIDGE\' WHEN ccr.lastmile_pct IS NOT NULL THEN \'CAT_REV_PCT\' ELSE \'NO_MATCH\' END AS lastmile_match_type, COALESCE( e.qty * e.direct_lastmile_per_unit_usd, e.qty * e.bridge_lastmile_per_unit_usd, e.product_revenue_local * ccr.lastmile_pct, 0 ) AS last_mile_usd_final FROM enriched e LEFT JOIN category_cost_ratios ccr ON ccr.category = e.category ), meta_campaigns_dim AS ( SELECT DISTINCT CAMPAIGN_ID, CAMPAIGN_NAME, ADSET_ID, ADSET_NAME, AD_ID, AD_NAME, CASE WHEN UPPER(CAMPAIGN_NAME) LIKE \'%COFFEE%\' THEN \'Coffee\' WHEN UPPER(CAMPAIGN_NAME) LIKE \'%SUPP%\' THEN \'Supplements\' ELSE \'Tea and Botanicals\' END AS mapped_category FROM vahdam_db.maplemonk.meta_usa_customcampaigns_data WHERE CAMPAIGN_NAME NOT ILIKE \'%AWAR%\' ), google_campaigns_dim AS ( SELECT DISTINCT CAMPAIGN_ID::STRING AS CAMPAIGN_ID, CAMPAIGN_NAME AS CAMPAIGN_NAME, CASE WHEN UPPER(CAMPAIGN_NAME) LIKE \'%COFFEE%\' THEN \'Coffee\' WHEN UPPER(CAMPAIGN_NAME) LIKE \'%SUPP%\' THEN \'Supplements\' ELSE \'Tea and Botanicals\' END AS mapped_category FROM vahdam_db.maplemonk.us_google_ads_consolidated ), line_with_marketing AS ( SELECT e.*, COALESCE(meta_cat.spend_usd, 0) AS meta_spend_category_day_usd, COALESCE(meta_unm.spend_usd, 0) AS meta_spend_unmapped_day_usd, COALESCE(goog_cat.spend_usd, 0) AS google_spend_category_day_usd, COALESCE(goog_unm.spend_usd, 0) AS google_spend_unmapped_day_usd, COALESCE(dcr.cat_product_revenue, 0) AS day_cat_product_revenue, SUM(COALESCE(dcr.cat_product_revenue,0)) OVER (PARTITION BY e.day) AS day_total_product_revenue, COALESCE(meta_ad.CAMPAIGN_NAME, meta_as.CAMPAIGN_NAME, meta_id.CAMPAIGN_NAME, goog_id.CAMPAIGN_NAME) AS matched_campaign_name, COALESCE(meta_ad.CAMPAIGN_ID, meta_as.CAMPAIGN_ID, meta_id.CAMPAIGN_ID, goog_id.CAMPAIGN_ID) AS matched_campaign_id, COALESCE(meta_ad.ADSET_NAME, meta_as.ADSET_NAME) AS matched_adset_name, COALESCE(meta_ad.ADSET_ID, meta_as.ADSET_ID) AS matched_adset_id, meta_ad.AD_NAME AS matched_ad_name, meta_ad.AD_ID AS matched_ad_id, COALESCE(meta_ad.mapped_category, meta_as.mapped_category, meta_id.mapped_category, goog_id.mapped_category) AS matched_campaign_category, CASE WHEN meta_ad.AD_ID IS NOT NULL THEN \'META_AD_ID_MATCH\' WHEN meta_as.ADSET_ID IS NOT NULL THEN \'META_ADSET_ID_MATCH\' WHEN meta_id.CAMPAIGN_ID IS NOT NULL THEN \'META_CAMPAIGN_ID_MATCH\' WHEN goog_id.CAMPAIGN_ID IS NOT NULL THEN \'GOOGLE_CAMPAIGN_ID_MATCH\' ELSE NULL END AS campaign_match_source, COALESCE(meta_nm.CAMPAIGN_ID, goog_nm.CAMPAIGN_ID) AS matched_by_name_campaign_id, COALESCE(meta_nm.mapped_category, goog_nm.mapped_category) AS matched_by_name_category FROM enriched_with_fallbacks e LEFT JOIN pm_day_source_cat meta_cat ON meta_cat.day = e.day AND meta_cat.source = \'META\' AND meta_cat.mapped_category = e.category LEFT JOIN pm_day_source_cat meta_unm ON meta_unm.day = e.day AND meta_unm.source = \'META\' AND meta_unm.mapped_category = \'UNMAPPED\' LEFT JOIN pm_day_source_cat goog_cat ON goog_cat.day = e.day AND goog_cat.source = \'GOOGLE\' AND goog_cat.mapped_category = e.category LEFT JOIN pm_day_source_cat goog_unm ON goog_unm.day = e.day AND goog_unm.source = \'GOOGLE\' AND goog_unm.mapped_category = \'UNMAPPED\' LEFT JOIN day_category_revenue dcr ON dcr.day = e.day AND dcr.category = e.category LEFT JOIN meta_campaigns_dim meta_ad ON meta_ad.AD_ID = e.order_utm_campaign LEFT JOIN meta_campaigns_dim meta_as ON meta_as.ADSET_ID = e.order_utm_campaign LEFT JOIN meta_campaigns_dim meta_id ON meta_id.CAMPAIGN_ID = e.order_utm_campaign LEFT JOIN google_campaigns_dim goog_id ON goog_id.CAMPAIGN_ID = e.order_utm_campaign LEFT JOIN meta_campaigns_dim meta_nm ON UPPER(meta_nm.CAMPAIGN_NAME) = UPPER(e.order_utm_campaign) LEFT JOIN google_campaigns_dim goog_nm ON UPPER(goog_nm.CAMPAIGN_NAME) = UPPER(e.order_utm_campaign) ), final_calc AS ( SELECT e.*, CASE WHEN pg_fee_usd_order IS NOT NULL THEN pg_fee_usd_order * line_share_of_order_revenue ELSE COALESCE(net_revenue_local, 0) * 0.025 END AS pg_fee_local, CASE WHEN pg_fee_usd_order IS NOT NULL THEN \'ACTUAL\' ELSE \'FALLBACK_2.5PCT\' END AS pg_match_type_v, CASE WHEN is_subscription_order THEN COALESCE(net_revenue_local, 0) * 0.007 ELSE 0 END AS loop_commission_local, COALESCE( meta_spend_category_day_usd * CASE WHEN day_cat_product_revenue > 0 THEN product_revenue_local / day_cat_product_revenue ELSE 0 END + meta_spend_unmapped_day_usd * CASE WHEN day_total_product_revenue > 0 THEN product_revenue_local / day_total_product_revenue ELSE 0 END , 0) AS meta_spend_local, COALESCE( google_spend_category_day_usd * CASE WHEN day_cat_product_revenue > 0 THEN product_revenue_local / day_cat_product_revenue ELSE 0 END + google_spend_unmapped_day_usd * CASE WHEN day_total_product_revenue > 0 THEN product_revenue_local / day_total_product_revenue ELSE 0 END , 0) AS google_spend_local FROM line_with_marketing e ), mis_raw AS ( SELECT TRIM(\"MIS Head\") AS mis, DATE_FROM_PARTS(2000 + TRY_TO_NUMBER(SPLIT_PART(mth,\'-\',2)), DECODE(UPPER(SPLIT_PART(mth,\'-\',1)),\'JAN\',1,\'FEB\',2,\'MAR\',3,\'APR\',4,\'MAY\',5,\'JUN\',6, \'JUL\',7,\'AUG\',8,\'SEP\',9,\'OCT\',10,\'NOV\',11,\'DEC\',12), 1) AS month_start, TRY_TO_DECIMAL(REPLACE(NULLIF(TRIM(val),\'\'),\',\',\'\'),30,4) AS amt_inr FROM vahdam_db.maplemonk1.tool_costs_sheet_to_fill__aug_26_onwards_ UNPIVOT INCLUDE NULLS (val FOR mth IN (\"Apr-26\",\"May-26\",\"Jun-26\",\"Jul-26\",\"Aug-26\",\"Sep-26\", \"Oct-26\",\"Nov-26\",\"Dec-26\",\"Jan-27\",\"Feb-27\",\"Mar-27\")) WHERE UPPER(TRIM(\"Channel Group\")) = \'D2C\' AND UPPER(TRIM(\"GEO\")) = \'USA\' ), mis_month AS ( SELECT mis, month_start, SUM(amt_inr) AS amt_inr FROM mis_raw GROUP BY 1,2 ), mis_filled AS ( SELECT mis, month_start, COALESCE(amt_inr, AVG(amt_inr) OVER (PARTITION BY mis ORDER BY month_start ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) AS amt_used_inr, IFF(amt_inr IS NULL, 1, 0) AS is_imputed FROM mis_month ), mis_wide AS ( SELECT month_start, SUM(IFF(mis = \'Agency Cost\', amt_used_inr, 0)) AS agency_inr, SUM(IFF(mis ILIKE \'Software and Platform Fee%\', amt_used_inr, 0)) AS software_inr, MAX(IFF(mis = \'Agency Cost\', is_imputed, 0)) AS agency_imputed, MAX(IFF(mis ILIKE \'Software and Platform Fee%\', is_imputed, 0)) AS software_imputed FROM mis_filled GROUP BY 1 ), final_calc2 AS ( SELECT c.*, c.meta_spend_local + c.google_spend_local AS pm_spend_total_local, CASE WHEN c.day >= DATE \'2026-04-01\' AND COALESCE(c.day_total_product_revenue,0) > 0 THEN COALESCE(mw.agency_inr,0) / DAY(LAST_DAY(c.day)) / 90.53 * (c.product_revenue_local / c.day_total_product_revenue) ELSE 0 END AS agency_cost_local, CASE WHEN c.day >= DATE \'2026-04-01\' AND COALESCE(c.day_total_product_revenue,0) > 0 THEN COALESCE(mw.software_inr,0) / DAY(LAST_DAY(c.day)) / 90.53 * (c.product_revenue_local / c.day_total_product_revenue) ELSE 0 END AS software_platform_fee_local, IFF(c.day >= DATE \'2026-04-01\', COALESCE(mw.agency_imputed,0), 0) AS agency_cost_imputed, IFF(c.day >= DATE \'2026-04-01\', COALESCE(mw.software_imputed,0), 0) AS software_platform_fee_imputed, COALESCE(c.net_revenue_local, 0) - COALESCE(c.cogs_usd_final, 0) - COALESCE(c.duty_usd_final, 0) - COALESCE(c.outbound_usd_final, 0) - COALESCE(c.last_mile_usd_final, 0) - c.pg_fee_local - c.loop_commission_local AS cm1_local FROM final_calc c LEFT JOIN mis_wide mw ON mw.month_start = DATE_TRUNC(\'MONTH\', c.day) ) SELECT \'US\' AS geography, c.day, c.ORDER_TIMESTAMP, c.ORDER_ID, c.ORDER_NAME, c.TAGS, c.LINE_ITEM_ID, c.line_item_sku, c.common_sku_id, c.common_sku_description, c.brand, c.category, c.sub_category, c.PRODUCT_NAME, c.VARIANT_NAME, c.line_type, c.qty, c.vat_rate, ROUND(c.gross_sales_local * 90.53, 4) AS gross_sales_inr, ROUND(c.gross_sales_local, 4) AS gross_sales_usd, ROUND(c.gross_sales_local * 90.53 / 121.05, 4) AS gross_sales_gbp, ROUND(c.discount_local * 90.53, 4) AS discount_inr, ROUND(c.discount_local, 4) AS discount_usd, ROUND(c.discount_local * 90.53 / 121.05, 4) AS discount_gbp, ROUND(c.net_sales_local_raw * 90.53, 4) AS net_sales_raw_inr, ROUND(c.net_sales_local_raw, 4) AS net_sales_raw_usd, ROUND(c.net_sales_local_raw * 90.53 / 121.05, 4) AS net_sales_raw_gbp, ROUND(c.product_revenue_local * 90.53, 4) AS product_revenue_inr, ROUND(c.product_revenue_local, 4) AS product_revenue_usd, ROUND(c.product_revenue_local * 90.53 / 121.05, 4) AS product_revenue_gbp, ROUND(c.product_revenue_net_local * 90.53, 4) AS product_revenue_net_of_refunds_inr, ROUND(c.product_revenue_net_local, 4) AS product_revenue_net_of_refunds_usd, ROUND(c.product_revenue_net_local * 90.53 / 121.05, 4) AS product_revenue_net_of_refunds_gbp, ROUND(c.product_revenue_net_ex_vat_local * 90.53, 4) AS product_revenue_net_ex_vat_inr, ROUND(c.product_revenue_net_ex_vat_local, 4) AS product_revenue_net_ex_vat_usd, ROUND(c.product_revenue_net_ex_vat_local * 90.53 / 121.05, 4) AS product_revenue_net_ex_vat_gbp, ROUND(c.net_revenue_local * 90.53, 4) AS net_revenue_inr, ROUND(c.net_revenue_local, 4) AS net_revenue_usd, ROUND(c.net_revenue_local * 90.53 / 121.05, 4) AS net_revenue_gbp, ROUND(c.cogs_usd_final * 90.53, 4) AS cogs_inr, ROUND(c.cogs_usd_final, 4) AS cogs_usd, ROUND(c.cogs_usd_final * 90.53 / 121.05, 4) AS cogs_gbp, ROUND(c.duty_usd_final * 90.53, 4) AS duty_inr, ROUND(c.duty_usd_final, 4) AS duty_usd, ROUND(c.duty_usd_final * 90.53 / 121.05, 4) AS duty_gbp, ROUND(c.outbound_usd_final * 90.53, 4) AS outbound_inr, ROUND(c.outbound_usd_final, 4) AS outbound_usd, ROUND(c.outbound_usd_final * 90.53 / 121.05, 4) AS outbound_gbp, ROUND(c.last_mile_usd_final * 90.53, 4) AS last_mile_inr, ROUND(c.last_mile_usd_final, 4) AS last_mile_usd, ROUND(c.last_mile_usd_final * 90.53 / 121.05, 4) AS last_mile_gbp, CAST(0 AS NUMBER(18,4)) AS three_pl_inr, CAST(0 AS NUMBER(18,4)) AS three_pl_usd, CAST(0 AS NUMBER(18,4)) AS three_pl_gbp, CAST(0 AS NUMBER(18,4)) AS storage_inr, CAST(0 AS NUMBER(18,4)) AS storage_usd, CAST(0 AS NUMBER(18,4)) AS storage_gbp, ROUND(c.pg_fee_local * 90.53, 4) AS pg_fee_inr, ROUND(c.pg_fee_local, 4) AS pg_fee_usd, ROUND(c.pg_fee_local * 90.53 / 121.05, 4) AS pg_fee_gbp, ROUND(c.loop_commission_local * 90.53, 4) AS loop_commission_inr, ROUND(c.loop_commission_local, 4) AS loop_commission_usd, ROUND(c.loop_commission_local * 90.53 / 121.05, 4) AS loop_commission_gbp, ROUND(c.meta_spend_local * 90.53, 4) AS meta_spend_inr, ROUND(c.meta_spend_local, 4) AS meta_spend_usd, ROUND(c.meta_spend_local * 90.53 / 121.05, 4) AS meta_spend_gbp, ROUND(c.google_spend_local * 90.53, 4) AS google_spend_inr, ROUND(c.google_spend_local, 4) AS google_spend_usd, ROUND(c.google_spend_local * 90.53 / 121.05, 4) AS google_spend_gbp, ROUND(c.pm_spend_total_local * 90.53, 4) AS pm_spend_total_inr, ROUND(c.pm_spend_total_local, 4) AS pm_spend_total_usd, ROUND(c.pm_spend_total_local * 90.53 / 121.05, 4) AS pm_spend_total_gbp, ROUND(c.agency_cost_local * 90.53, 4) AS agency_cost_inr, ROUND(c.agency_cost_local, 4) AS agency_cost_local_ccy, ROUND(c.software_platform_fee_local * 90.53, 4) AS software_platform_fee_inr, ROUND(c.software_platform_fee_local, 4) AS software_platform_fee_local_ccy, c.agency_cost_imputed, c.software_platform_fee_imputed, ROUND((c.pm_spend_total_local + c.agency_cost_local + c.software_platform_fee_local) * 90.53, 4) AS cm1_to_cm2_costs_inr, ROUND(c.pm_spend_total_local + c.agency_cost_local + c.software_platform_fee_local, 4) AS cm1_to_cm2_costs_local_ccy, CASE WHEN c.day_cat_product_revenue > 0 THEN c.product_revenue_local / c.day_cat_product_revenue ELSE 0 END AS line_share_of_day_category_revenue, CASE WHEN c.day_total_product_revenue > 0 THEN c.product_revenue_local / c.day_total_product_revenue ELSE 0 END AS line_share_of_day_total_revenue, ROUND(c.cm1_local * 90.53, 4) AS cm1_inr, ROUND(c.cm1_local, 4) AS cm1_usd, ROUND(c.cm1_local * 90.53 / 121.05, 4) AS cm1_gbp, ROUND((c.cm1_local - c.pm_spend_total_local - c.agency_cost_local - c.software_platform_fee_local) * 90.53, 4) AS cm2_inr, ROUND(c.cm1_local - c.pm_spend_total_local - c.agency_cost_local - c.software_platform_fee_local, 4) AS cm2_usd, ROUND((c.cm1_local - c.pm_spend_total_local - c.agency_cost_local - c.software_platform_fee_local) * 90.53 / 121.05, 4) AS cm2_gbp, c.refund_qty, c.IS_REFUND AS is_refund, ROUND(c.refund_value_local * 90.53, 4) AS refund_value_inr, ROUND(c.refund_value_local, 4) AS refund_value_usd, ROUND(c.refund_value_local * 90.53 / 121.05, 4) AS refund_value_gbp, ROUND(c.shipping_price_order_local * 90.53, 4) AS shipping_price_order_inr, ROUND(c.shipping_price_order_local, 4) AS shipping_price_order_usd, ROUND(c.shipping_price_order_local * 90.53 / 121.05, 4) AS shipping_price_order_gbp, ROUND(c.discount_order_local * 90.53, 4) AS discount_order_inr, ROUND(c.discount_order_local, 4) AS discount_order_usd, ROUND(c.discount_order_local * 90.53 / 121.05, 4) AS discount_order_gbp, ROUND(c.total_sales_order_local * 90.53, 4) AS total_sales_order_inr, ROUND(c.total_sales_order_local, 4) AS total_sales_order_usd, ROUND(c.total_sales_order_local * 90.53 / 121.05, 4) AS total_sales_order_gbp, c.order_total_qty, ROUND(c.order_total_product_revenue * 90.53, 4) AS order_total_product_revenue_inr, ROUND(c.order_total_product_revenue, 4) AS order_total_product_revenue_usd, ROUND(c.order_total_product_revenue * 90.53 / 121.05, 4) AS order_total_product_revenue_gbp, c.line_share_of_order_revenue, c.GATEWAY AS payment_gateway, c.PINCODE AS shipping_postcode, c.customer_email, c.customer_id, c.order_number_for_customer, c.is_first_order, c.is_repeat_order, c.customer_first_order_ts, c.days_since_first_order, c.days_since_prev_order, ROUND(c.customer_revenue_to_date * 90.53, 4) AS customer_revenue_to_date_inr, ROUND(c.customer_revenue_to_date, 4) AS customer_revenue_to_date_usd, ROUND(c.customer_revenue_to_date * 90.53 / 121.05, 4) AS customer_revenue_to_date_gbp, c.customer_units_to_date, c.is_subscription_order, c.is_subscription_first_order, c.is_subscription_recurring_order, c.billing_cycle_num, c.billing_interval_value, c.billing_interval_unit, CASE c.billing_interval_unit WHEN \'DAY\' THEN c.billing_interval_value WHEN \'WEEK\' THEN c.billing_interval_value * 7 WHEN \'MONTH\' THEN c.billing_interval_value * 30 ELSE NULL END AS billing_interval_days, (CASE c.billing_interval_unit WHEN \'DAY\' THEN c.billing_interval_value WHEN \'WEEK\' THEN c.billing_interval_value * 7 WHEN \'MONTH\' THEN c.billing_interval_value * 30 ELSE NULL END = 30) AS is_30_day_plan, c.acquisition_utm_source, c.acquisition_utm_channel, c.acquisition_utm_campaign, c.acquisition_mapped_channel, c.acquisition_mapped_source, c.order_utm_source, c.order_utm_channel, c.order_utm_campaign, c.order_mapped_channel, c.order_mapped_source, CASE WHEN c.is_subscription_recurring_order OR c.billing_cycle_num > 1 THEN \'SUBSCRIPTION_RENEWAL\' WHEN UPPER(c.order_utm_source) IN (\'META\',\'FACEBOOK\',\'FB\',\'INSTAGRAM\',\'IG\') THEN \'META\' WHEN UPPER(c.order_utm_source) IN (\'GOOGLE\',\'BING\',\'YAHOO\') THEN \'SEARCH\' WHEN UPPER(c.order_utm_source) IN (\'TIKTOK\') THEN \'TIKTOK\' WHEN UPPER(c.order_utm_source) IN (\'KLAVIYO\') THEN \'EMAIL\' WHEN UPPER(c.order_utm_source) IN (\'SHOP_APP\') THEN \'SHOP_APP\' WHEN c.order_utm_source ILIKE \'%vahdam%\' OR c.order_utm_source ILIKE \'%try.vahdam%\' THEN \'OWNED_LP\' WHEN UPPER(c.order_utm_source) = \'DIRECT\' THEN \'DIRECT\' WHEN c.order_utm_source IS NULL OR TRIM(c.order_utm_source) = \'\' THEN \'UNKNOWN\' ELSE \'OTHER\' END AS acquisition_channel_normalised, COALESCE( c.matched_campaign_category, c.matched_by_name_category, CASE WHEN UPPER(c.order_utm_campaign) LIKE \'%COFFEE%\' THEN \'Coffee\' WHEN UPPER(c.order_utm_campaign) LIKE \'%SUPP%\' THEN \'Supplements\' ELSE NULL END ) AS acquisition_product_category, c.matched_campaign_id, c.matched_campaign_name, c.matched_adset_id, c.matched_adset_name, c.matched_ad_id, c.matched_ad_name, c.matched_campaign_category, c.matched_by_name_campaign_id, c.cogs_match_type, c.duty_match_type, c.outbound_match_type, c.lastmile_match_type, c.pg_match_type_v AS pg_match_type, c.campaign_match_source, c.cat_cogs_pct, c.cat_duty_pct, c.cat_outbound_pct, c.cat_lastmile_pct, c.fx_inr_per_usd AS fx_inr_per_gbp FROM final_calc2 c ;",
